  "Crop Management": "\u10D9\u10E3\u10DA\u10E2\u10E3\u10E0\u10D4\u10D1\u10D8\u10E1 \u10DB\u10D0\u10E0\u10D7\u10D5\u10D0",
  "Delete Asset": "\u10DD\u10D1\u10D8\u10D4\u10E5\u10E2\u10D8\u10E1 \u10EC\u10D0\u10E8\u10DA\u10D0",
  "Rename Asset": "\u10D0\u10E5\u10E2\u10D8\u10D5\u10D8\u10E1 \u10E1\u10D0\u10EE\u10D4\u10DA\u10D8\u10E1 \u10E8\u10D4\u10EA\u10D5\u10DA\u10D0",
