  "Export / Import": "\u10D4\u10E5\u10E1\u10DE\u10DD\u10E0\u10E2\u10D8 / \u10D8\u10DB\u10DE\u10DD\u10E0\u10E2\u10D8",
  "Export / Import Theme JSON": "JSON \u10D7\u10D4\u10DB\u10D8\u10E1 \u10D4\u10E5\u10E1\u10DE\u10DD\u10E0\u10E2\u10D8/\u10D8\u10DB\u10DE\u10DD\u10E0\u10E2\u10D8",
  "Export Audit CSV": "\u10D0\u10E3\u10D3\u10D8\u10E2\u10D8\u10E1 \u10D4\u10E5\u10E1\u10DE\u10DD\u10E0\u10E2\u10D8 CSV",
