  Stock_Harvest_Produce: "\u10DB\u10D0\u10E0\u10D0\u10D2\u10D8_\u10DB\u10DD\u10E1\u10D0\u10D5\u10D0\u10DA\u10D8_\u10EC\u10D0\u10E0\u10DB\u10DD\u10D4\u10D1\u10D0",
