  "System Local Spooler": "\u10E1\u10D8\u10E1\u10E2\u10D4\u10DB\u10D8\u10E1 \u10DA\u10DD\u10D9\u10D0\u10DA\u10E3\u10E0\u10D8 \u10E1\u10DE\u10E3\u10DA\u10D4\u10E0\u10D8",
  "System Maintenance": "\u10E1\u10D8\u10E1\u10E2\u10D4\u10DB\u10D8\u10E1 \u10DB\u10DD\u10D5\u10DA\u10D0",
  "System Node Type": "\u10E1\u10D8\u10E1\u10E2\u10D4\u10DB\u10D8\u10E1 \u10D9\u10D5\u10D0\u10DC\u10EB\u10D8\u10E1 \u10E2\u10D8\u10DE\u10D8",
