  Wed: "\u10DD\u10D7\u10EE",
  "Weekly Cycle": "\u10E7\u10DD\u10D5\u10D4\u10DA\u10D9\u10D5\u10D8\u10E0\u10D4\u10E3\u10DA\u10D8 \u10EA\u10D8\u10D9\u10DA\u10D8",
  "Weigh Station Access": "\u10E1\u10D0\u10EC\u10DD\u10DC\u10D8\u10E1 \u10E1\u10D0\u10D3\u10D2\u10E3\u10E0\u10D6\u10D4 \u10EC\u10D5\u10D3\u10DD\u10DB\u10D0",
  "Weigh Station Peripheral Registry": "\u10D0\u10EC\u10DD\u10DC\u10D5\u10D8\u10E1 \u10E1\u10D0\u10D3\u10D2\u10E3\u10E0\u10D8\u10E1 \u10DE\u10D4\u10E0\u10D8\u10E4\u10D4\u10E0\u10D8\u10E3\u10DA\u10D8 \u10E0\u10D4\u10D4\u10E1\u10E2\u10E0\u10D8",
